type ExportFormat = "aaaa_sp" | "abcs_regular" | "leave_request" | "sp_report";
const exportFormatLabels: Record<ExportFormat, string> = { aaaa_sp: "SP派遣用作業実績表", abcs_regular: "ABCS正社員（普通）勤務表", leave_request: "休暇・遅刻・早退申請書", sp_report: "SP用作業報告書" };
type CurrentUser = { id: string; loginId: string; displayName: string; role: keyof typeof roleLabels; tenantId?: string; tenantName?: string; tenantIds?: string[]; tenantNames?: string[]; exportFormat?: ExportFormat; disabledAt?: string | null; suspendedAt?: string | null; twoFactorRequired?: boolean; twoFactorEnrolled?: boolean }; type TenantNav = { id: string; name: string }; type WorkspaceNav = { id: string; name: string; tenantId?: string; tenantName?: string };
const roleLabels = { system_admin: "システム管理者", system_operator: "システム作業者", verifier: "検証者", member: "メンバー" } as const;
const passwordPolicy = /^(?=.{8,20}$)(?=.*[A-Za-z])(?=.*\d)(?=.*[^A-Za-z0-9])[\x21-\x7E]+$/;
const postalCodePolicy = /^(?:\d{7}|\d{3}-\d{4})$/;
function isValidPostalCode(value: string) { return value === "" || postalCodePolicy.test(value); }
function passwordStrength(value: string) { let score = 0; if (value.length >= 8) score += 1; if (value.length >= 12) score += 1; if (/[A-Za-z]/.test(value) && /\d/.test(value)) score += 1; if (/[^A-Za-z0-9]/.test(value)) score += 1; return ["未入力", "弱い", "普通", "強い", "非常に強い"][score]; }
async function apiJson<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, init); if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.error?.message ?? "処理に失敗しました"); } return response.status === 204 ? (undefined as T) : response.json(); }

