function TenantSidebar({ user }: { user: CurrentUser | null }) { const [tenants, setTenants] = useState<TenantNav[]>([]); const [workspaces, setWorkspaces] = useState<WorkspaceNav[]>([]); const [collapsed, setCollapsed] = useState<Record<string, boolean>>({}); useEffect(() => { if (!user) return; apiJson<{ tenants: TenantNav[] }>("/api/v1/tenants").then((result) => setTenants(result.tenants)).catch(() => undefined); apiJson<{ workspaces: WorkspaceNav[] }>("/api/v1/workspaces").then((result) => setWorkspaces(result.workspaces)).catch(() => undefined); }, [user?.id]); return <div className="tenant-sidebar">{tenants.map((tenant) => <details key={tenant.id} open={!collapsed[tenant.id]} onToggle={(event) => { const isOpen = (event.currentTarget as HTMLDetailsElement).open; setCollapsed((current) => ({ ...current, [tenant.id]: !isOpen })); }}><summary>{tenant.name}</summary><div className="tenant-links">{workspaces.filter((workspace) => workspace.tenantId === tenant.id).map((workspace) => <a key={workspace.id} href={`/workspaces/${workspace.id}`} onClick={(event) => { event.preventDefault(); navigate(`/workspaces/${workspace.id}`); }}>📁 {workspace.name}</a>)}<a href="/account" onClick={(event) => { event.preventDefault(); navigate("/account"); }}>⚙ アカウント設定</a></div></details>)}</div>; }
