function DashboardPage() { return <Shell><main className="page"><PageHeader title="マイドキュメント" description="自分の勤怠データを入力・提出・出力できます。" /><Toolbar onCreate={() => navigate("/attendance")} /><section className="file-list" aria-label="勤怠入力メニュー"><div className="file-list-head"><span>入力画面</span><span>内容</span><span>出力</span><span /></div>{([ ["勤務実績", "日々の開始・終了・休憩・案件", "勤怠表"], ["休暇・遅刻・早退申請", "休暇や遅刻・早退の申請", "申請書"], ["経費精算", "経費の明細と金額", "勤務表／経費"], ["月次報告書", "月の実績・課題・次月予定", "SP用報告書"] ] as const).map(([name, description, output]) => <div className="file-row" key={name}><div className="file-name"><span className="file-icon"><Icon name="file" /></span><div><a href="/attendance" onClick={(event) => { event.preventDefault(); navigate("/attendance"); }}>{name}</a></div></div><div className="muted-cell">{description}</div><div className="muted-cell">{output}</div><button className="row-action" onClick={() => navigate("/attendance")}>開く <Icon name="chevron" /></button></div>)}</section><div className="tip-card"><span className="tip-icon">i</span><div><strong>勤怠データを画面で管理します</strong><p>入力したデータを保存し、提出者のアカウントに割り当てられた形式でExcelを生成します。</p></div></div></main></Shell>; }

function LoginPage() { const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false); async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(null); setBusy(true); const form = new FormData(event.currentTarget); try { const response = await fetch("/api/v1/auth/password/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ loginId: form.get("loginId"), password: form.get("password") }) }); const result = await response.json().catch(() => null); if (!response.ok) throw new Error(response.status === 401 ? "ログインIDまたはパスワードが正しくありません" : "ログインサービスに接続できません"); navigate(result?.twoFactor?.required && !result?.twoFactor?.verified ? "/account/2fa" : "/dashboard"); } catch (cause) { setError(cause instanceof Error ? cause.message : "ログインに失敗しました"); } finally { setBusy(false); } } return <main className="login-page"><div className="login-brand"><span className="brand-mark">T</span><strong>Timesheet Portal</strong></div><div className="login-card"><p className="eyebrow">TIMESHEET PORTAL</p><h1>勤務表を、確実に提出する。</h1><p>ログインして、勤務表のファイルを管理しましょう。</p><form className="login-form" onSubmit={submit}><label htmlFor="loginId">ログインID</label><input id="loginId" name="loginId" type="text" autoComplete="username" required /><label htmlFor="password">パスワード</label><input id="password" name="password" type="password" autoComplete="current-password" required />{error && <p className="form-error" role="alert">{error}</p>}<button type="submit" disabled={busy}>{busy ? "ログイン中…" : "ログイン"}</button></form><p className="login-note">アカウントについては管理者に確認してください。</p></div></main>; }
type AttendanceEntry = { id: string; work_date: string; start_time?: string | null; end_time?: string | null; break_minutes: number; ordinary_break_minutes?: number | null; night_break_minutes?: number | null; project_name?: string | null; note?: string | null };
type LeaveRequest = { id: string; start_date: string; end_date: string; leave_type: string; reason?: string | null; status: string };
type ExpenseItem = { id: string; expense_date: string; category: string; amount: number; description?: string | null };
function AttendancePage() {
  const defaultMonth = new Date().toISOString().slice(0, 7);
  const [tab, setTab] = useState<"work" | "leave" | "expense" | "report">("work");
  const [month, setMonth] = useState(defaultMonth);
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [profile, setProfile] = useState<Record<string, string>>({});
  const [entries, setEntries] = useState<AttendanceEntry[]>([]);
  const [leaves, setLeaves] = useState<LeaveRequest[]>([]);
  const [expenses, setExpenses] = useState<ExpenseItem[]>([]);
  const [report, setReport] = useState({ summary: "", achievements: "", nextSteps: "", overtimeComment: "" });
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [entry, setEntry] = useState({ workDate: `${defaultMonth}-01`, startTime: "09:00", endTime: "17:30", ordinaryBreakMinutes: "", nightBreakMinutes: "", projectName: "", note: "" });
  const [leave, setLeave] = useState({ startDate: `${defaultMonth}-01`, endDate: `${defaultMonth}-01`, leaveType: "年休", reason: "" });
  const [expense, setExpense] = useState({ expenseDate: `${defaultMonth}-01`, category: "交通費", amount: "", description: "" });
  const elevated = user?.role === "system_admin" || user?.role === "system_operator" || user?.role === "verifier";
  async function load() { setError(null); try { const [me, data] = await Promise.all([apiJson<{ user: CurrentUser }>("/api/v1/auth/me"), apiJson<{ profile: Record<string, unknown> | null; entries: AttendanceEntry[]; leaveRequests: LeaveRequest[]; expenses: ExpenseItem[]; report: { summary?: string; achievements?: string; next_steps?: string; overtime_comment?: string } | null }>(`/api/v1/attendance/month?month=${encodeURIComponent(month)}`)]); setUser(me.user); setProfile(Object.fromEntries(Object.entries(data.profile ?? {}).filter(([key]) => key !== "user_id" && key !== "display_name" && key !== "created_at" && key !== "updated_at").map(([key, value]) => [key.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase()), String(value ?? "")]))); setEntries(data.entries); setLeaves(data.leaveRequests); setExpenses(data.expenses); const reportBody = [data.report?.summary, data.report?.achievements, data.report?.next_steps].filter((value): value is string => Boolean(value?.trim())).join("\n\n"); setReport({ summary: reportBody, achievements: "", nextSteps: "", overtimeComment: data.report?.overtime_comment ?? "" }); } catch (cause) { setError(cause instanceof Error ? cause.message : "勤怠データの読み込みに失敗しました"); } }
  useEffect(() => { void load(); }, [month]);
  async function saveProfile() { setError(null); const invalidPostal = (["dispatchDestinationPostalCode", "workLocationPostalCode"] as const).find((key) => !isValidPostalCode(profile[key] ?? "")); if (invalidPostal) { setError("郵便番号は7桁、または xxx-xxxx 形式で入力してください"); return; } try { await apiJson("/api/v1/attendance/profile", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(profile) }); setMessage("共通項目を保存しました"); } catch (cause) { setError(cause instanceof Error ? cause.message : "共通項目の保存に失敗しました"); } }
  async function addEntry(event: FormEvent) { event.preventDefault(); try { await apiJson("/api/v1/attendance/entries", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...entry, targetMonth: month, ordinaryBreakMinutes: Number(entry.ordinaryBreakMinutes), nightBreakMinutes: Number(entry.nightBreakMinutes) }) }); setMessage("勤務実績を保存しました"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "勤務実績の保存に失敗しました"); } }
  async function addLeave(event: FormEvent) { event.preventDefault(); try { await apiJson("/api/v1/attendance/leave", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...leave, targetMonth: month }) }); setMessage("申請を保存しました"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "申請の保存に失敗しました"); } }
  async function addExpense(event: FormEvent) { event.preventDefault(); try { await apiJson("/api/v1/attendance/expenses", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...expense, targetMonth: month, amount: Number(expense.amount) }) }); setMessage("経費を保存しました"); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "経費の保存に失敗しました"); } }
  async function saveMonthlyReport() { try { await apiJson("/api/v1/attendance/monthly-report", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ summary: report.summary, achievements: "", nextSteps: "", overtimeComment: report.overtimeComment, targetMonth: month }) }); setMessage("月次報告を保存しました"); } catch (cause) { setError(cause instanceof Error ? cause.message : "月次報告の保存に失敗しました"); } }
  async function saveReport(event: FormEvent) { event.preventDefault(); await saveMonthlyReport(); }
  async function downloadExcel() { setError(null); try { const params = new URLSearchParams({ month }); if (elevated) params.set("format", user?.exportFormat ?? "abcs_regular"); const response = await fetch(`/api/v1/attendance/export?${params.toString()}`); if (!response.ok) { const body = await response.json().catch(() => null); throw new Error(body?.error?.message ?? "Excelの生成に失敗しました"); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); const disposition = response.headers.get("Content-Disposition") ?? ""; const encodedFilename = disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1]; const filename = encodedFilename ? decodeURIComponent(encodedFilename) : disposition.match(/filename="?([^";]+)"?/i)?.[1] ?? "勤怠出力.xlsx"; link.href = url; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); } catch (cause) { const message = cause instanceof Error ? cause.message : "Excelの生成に失敗しました"; setError(message); window.alert(message); } }
  useEffect(() => { const link = document.querySelector<HTMLAnchorElement>('a[href^="/api/v1/attendance/export"]'); if (!link) return; const handleClick = (event: MouseEvent) => { event.preventDefault(); void downloadExcel(); }; link.addEventListener("click", handleClick); return () => link.removeEventListener("click", handleClick); }, [month, elevated, user?.exportFormat]);
  async function submit() { try { await apiJson("/api/v1/attendance/submit", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ targetMonth: month }) }); setMessage("提出しました"); } catch (cause) { setError(cause instanceof Error ? cause.message : "提出に失敗しました"); } }
  const profileFields: Array<[keyof typeof profile, string]> = [["employeeCode", "社員コード"], ["nameKana", "氏名カナ"], ["companyName", "会社名"], ["divisionName", "所属事業部名"], ["departmentName", "所属部署名"], ["projectName", "案件名"], ["clientName", "顧客名"], ["dispatchWorkContent", "派遣業務内容"], ["dispatchDestinationOfficeName", "派遣先事業所名"], ["dispatchDestinationAddress", "派遣先住所"], ["workLocationOrgUnit", "就業場所組織単位"], ["workLocationAddress", "就業場所住所"]];
  const updateProfile = (key: string, value: string) => setProfile((current) => ({ ...current, [key]: value }));
return <Shell><main className="page"><PageHeader eyebrow="勤怠入力" title="勤怠データ" description="ファイルをアップロードせず、4つの入力画面から勤務情報を登録します。"><div className="header-actions"><label className="month-picker">対象年月<input type="month" value={month} onChange={(event) => setMonth(event.target.value)} /></label></div></PageHeader><section className="panel common-profile-panel"><div className="section-heading"><div><h2>共通項目</h2><p className="field-help">Excel出力の共通欄に使用します。</p></div><span className="folder-badge">{user?.exportFormat ? exportFormatLabels[user.exportFormat] : "読み込み中"}</span></div><div className="common-profile-grid">{profileFields.map(([key, label]) => <label key={key}>{label}<input value={profile[key] ?? ""} onChange={(event) => updateProfile(String(key), event.target.value)} /></label>)}<label>派遣先郵便番号<input value={profile.dispatchDestinationPostalCode ?? ""} onChange={(event) => updateProfile("dispatchDestinationPostalCode", event.target.value)} pattern="(?:[0-9]{7}|[0-9]{3}-[0-9]{4})" maxLength={8} inputMode="numeric" placeholder="例：9200000 または 920-0000" /></label><label>就業場所郵便番号<input value={profile.workLocationPostalCode ?? ""} onChange={(event) => updateProfile("workLocationPostalCode", event.target.value)} pattern="(?:[0-9]{7}|[0-9]{3}-[0-9]{4})" maxLength={8} inputMode="numeric" placeholder="例：9200000 または 920-0000" /></label><label>勤務形態<select value={profile.workPattern ?? ""} onChange={(event) => updateProfile("workPattern", event.target.value)}><option value="">選択してください</option><option value="通常勤務">通常勤務</option><option value="シフト勤務">シフト勤務</option></select></label><label>法定休日<select value={profile.statutoryHoliday ?? ""} onChange={(event) => updateProfile("statutoryHoliday", event.target.value)}><option value="">選択してください</option>{["日", "月", "火", "水", "木", "金", "土", "定まっていない"].map((day) => <option key={day} value={day}>{day}</option>)}</select></label></div><div className="form-actions"><button type="button" className="secondary-button" onClick={() => void saveProfile()}>共通項目を保存</button>{elevated && <label>出力形式<select value={user?.exportFormat ?? "abcs_regular"} onChange={(event) => setUser((current) => current ? { ...current, exportFormat: event.target.value as ExportFormat } : current)}>{Object.entries(exportFormatLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>}</div></section><div className="attendance-tabs" role="tablist">{([ ["work", "勤務実績"], ["leave", "休暇・遅刻・早退申請"], ["expense", "経費精算"], ["report", "月次報告書"] ] as const).map(([value, label]) => <button key={value} type="button" className={tab === value ? "active" : ""} onClick={() => setTab(value)}>{label}</button>)}</div>{error && <p className="form-error" role="alert">{error}</p>}{message && <p className="form-success" role="status">{message}</p>}{tab === "work" && <section className="panel attendance-panel"><h2>勤務実績</h2><form className="attendance-entry-form" onSubmit={addEntry}><label>勤務日<input type="date" value={entry.workDate} onChange={(event) => setEntry({ ...entry, workDate: event.target.value })} required /></label><label>開始<input type="time" value={entry.startTime} onChange={(event) => setEntry({ ...entry, startTime: event.target.value })} /></label><label>終了<input type="time" value={entry.endTime} onChange={(event) => setEntry({ ...entry, endTime: event.target.value })} /></label><label>普通休憩（分）<input type="number" min="0" max="1440" value={entry.ordinaryBreakMinutes} onChange={(event) => setEntry({ ...entry, ordinaryBreakMinutes: event.target.value })} /></label><label>深夜休憩（分）<input type="number" min="0" max="1440" value={entry.nightBreakMinutes} onChange={(event) => setEntry({ ...entry, nightBreakMinutes: event.target.value })} /></label><label>プロジェクト<input value={entry.projectName} onChange={(event) => setEntry({ ...entry, projectName: event.target.value })} /></label><label>備考<input value={entry.note} onChange={(event) => setEntry({ ...entry, note: event.target.value })} /></label><button className="primary-button">保存</button></form><form className="work-report-note" onSubmit={saveReport}><label>当月残業・勤務実績メモ<span className="field-help">残業に対するコメントや、勤務実績に関する補足を記入します。</span><textarea value={report.overtimeComment} onChange={(event) => setReport({ ...report, overtimeComment: event.target.value })} rows={4} /></label><button className="secondary-button">メモを保存</button></form><div className="attendance-table"><div className="attendance-table-head"><span>日付</span><span>時間</span><span>普通休憩</span><span>深夜休憩</span><span>プロジェクト</span></div>{entries.map((item) => <div className="attendance-table-row" key={item.id}><span>{item.work_date}</span><span>{item.start_time ?? ""} - {item.end_time ?? ""}</span><span>{item.ordinary_break_minutes ?? item.break_minutes}分</span><span>{item.night_break_minutes ?? 0}分</span><span>{item.project_name ?? ""}</span></div>)}{!entries.length && <p className="field-help">勤務実績はまだありません。</p>}</div></section>}{tab === "leave" && <section className="panel attendance-panel"><h2>休暇・遅刻・早退申請</h2><form className="attendance-entry-form" onSubmit={addLeave}><label>開始日<input type="date" value={leave.startDate} onChange={(event) => setLeave({ ...leave, startDate: event.target.value })} required /></label><label>終了日<input type="date" value={leave.endDate} onChange={(event) => setLeave({ ...leave, endDate: event.target.value })} required /></label><label>種別<select value={leave.leaveType} onChange={(event) => setLeave({ ...leave, leaveType: event.target.value })}><option>年休</option><option>遅刻</option><option>早退</option><option>特別休暇</option></select></label><label>理由<input value={leave.reason} onChange={(event) => setLeave({ ...leave, reason: event.target.value })} /></label><button className="primary-button">申請を保存</button></form>{leaves.map((item) => <div className="attendance-list-row" key={item.id}><strong>{item.start_date} - {item.end_date}</strong><span>{item.leave_type}</span><small>{item.reason}</small></div>)}{!leaves.length && <p className="field-help">申請はまだありません。</p>}</section>}{tab === "expense" && <section className="panel attendance-panel"><h2>経費精算</h2><form className="attendance-entry-form" onSubmit={addExpense}><label>利用日<input type="date" value={expense.expenseDate} onChange={(event) => setExpense({ ...expense, expenseDate: event.target.value })} required /></label><label>区分<input value={expense.category} onChange={(event) => setExpense({ ...expense, category: event.target.value })} required /></label><label>金額（円）<input type="number" min="0" value={expense.amount} onChange={(event) => setExpense({ ...expense, amount: event.target.value })} required /></label><label>内容<input value={expense.description} onChange={(event) => setExpense({ ...expense, description: event.target.value })} /></label><button className="primary-button">経費を保存</button></form>{expenses.map((item) => <div className="attendance-list-row" key={item.id}><strong>{item.expense_date}</strong><span>{item.category} / {item.amount.toLocaleString()}円</span><small>{item.description}</small></div>)}{!expenses.length && <p className="field-help">経費はまだありません。</p>}</section>}{tab === "report" && <section className="panel attendance-panel"><h2>月次報告書</h2><form className="report-form" onSubmit={saveReport}><label>報告欄<span className="field-help">当月の作業内容、実績・成果、課題、次月予定などを自由に記入してください。</span><textarea className="monthly-report-textarea" value={report.summary} onChange={(event) => setReport({ ...report, summary: event.target.value })} rows={27} /></label><button className="primary-button">月次報告を保存</button></form></section>}<div className="attendance-actions"><button className="secondary-button" type="button" onClick={() => void submit()}>この月を提出</button><a className="primary-button" href={`/api/v1/attendance/export?month=${encodeURIComponent(month)}${elevated ? `&format=${encodeURIComponent(user?.exportFormat ?? "abcs_regular")}` : ""}`}>Excelを生成・ダウンロード</a></div></main></Shell>;
}
function TimesheetDetailPage() { const [editing, setEditing] = useState(false); return <Shell><main className="page"><PageHeader eyebrow="2026年11月.xlsx" title="2026年11月.xlsx" description="勤務表 / 2026年度"><div className="header-actions"><button className="secondary-button"><Icon name="download" />ダウンロード</button><button className="primary-button" onClick={() => setEditing(true)}>{editing ? "編集中" : "編集する"}</button></div></PageHeader><div className="file-meta"><span><strong>状態</strong><StatusBadge status="draft" /></span><span><strong>最終更新</strong>2026/11/16 18:20</span><span><strong>サイズ</strong>84 KB</span><span><strong>バージョン</strong>v3</span></div>{editing ? <section className="edit-panel"><div className="edit-heading"><div><p className="eyebrow">編集中</p><h2>ファイルを編集して提出</h2><p>次の3ステップで完了します。編集中は他の人がこのファイルを更新できません。</p></div><span className="lock-note">編集状態を保持中</span></div><div className="edit-steps"><div className="edit-step done"><span>1</span><div><strong>ファイルをダウンロード</strong><small>Excelで開いて編集します</small></div><button className="secondary-button"><Icon name="download" />ダウンロード</button></div><div className="edit-step"><span>2</span><div><strong>編集済みファイルをアップロード</strong><small>保存した.xlsxファイルを選択します</small></div><label className="upload-button"><Icon name="upload" />ファイルを選択<input type="file" accept=".xlsx" /></label></div><div className="edit-step"><span>3</span><div><strong>提出する</strong><small>承認者へ提出します</small></div><button className="primary-button" onClick={() => navigate("/dashboard")}>提出する</button></div></div><button className="cancel-link" onClick={() => setEditing(false)}>編集をやめる</button></section> : <section className="empty-action"><div className="large-file-icon"><Icon name="file" /></div><h2>この勤務表を編集しますか？</h2><p>「編集する」を押すと、ファイルをダウンロードして編集を開始できます。</p><button className="primary-button" onClick={() => setEditing(true)}>編集する</button></section>}<div className="history-link"><button className="text-button">変更履歴を見る</button></div></main></Shell>; }
function ApprovalsPage() { const [submissions, setSubmissions] = useState<Array<{ id: string; timesheetId: string; targetMonth: string; submittedAt: string; employeeName: string; version: number }>>([]); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ submissions: typeof submissions }>("/api/v1/approvals").then((result) => setSubmissions(result.submissions)).catch((cause) => setError(cause instanceof Error ? cause.message : "承認待ちの読み込みに失敗しました")); useEffect(() => { void load(); }, []); async function decide(id: string, action: "approve" | "reject") { const reason = action === "reject" ? window.prompt("差し戻し理由を入力してください") : undefined; if (action === "reject" && !reason?.trim()) return; try { await apiJson(`/api/v1/approvals/${id}/${action}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(reason ? { reason } : {}) }); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "承認処理に失敗しました"); } } return <Shell><main className="page"><PageHeader title="承認待ち" description="あなたが確認する勤務表です。" />{error && <p className="form-error">{error}</p>}<div className="file-list"><div className="file-list-head"><span>対象月</span><span>状態</span><span>提出日</span><span>提出者</span><span /></div>{submissions.map((submission) => <div className="file-row" key={submission.id}><div className="file-name"><span className="file-icon"><Icon name="file" /></span><div><a href={`/timesheets/${submission.timesheetId}`}>{submission.targetMonth}.xlsx</a><small>v{submission.version}</small></div></div><StatusBadge status="submitted" /><div className="muted-cell">{new Date(submission.submittedAt).toLocaleDateString("ja-JP")}</div><div className="muted-cell">{submission.employeeName}</div><div className="user-actions"><button className="text-button" onClick={() => void decide(submission.id, "approve")}>承認</button><button className="text-button danger-button" onClick={() => void decide(submission.id, "reject")}>差し戻し</button></div></div>)}{!submissions.length && <p className="field-help">承認待ちの提出はありません。</p>}</div></main></Shell>; }
function AccountPage() { const [currentPassword, setCurrentPassword] = useState(""); const [password, setPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [message, setMessage] = useState<string | null>(null); const [error, setError] = useState<string | null>(null); async function submit(event: FormEvent) { event.preventDefault(); setError(null); setMessage(null); if (!passwordPolicy.test(password)) { setError("英字・数字・記号を含む8〜20文字で入力してください"); return; } if (password !== confirmation) { setError("新しいパスワードが一致しません"); return; } try { await apiJson("/api/v1/auth/password/change", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ currentPassword, password, passwordConfirmation: confirmation }) }); setCurrentPassword(""); setPassword(""); setConfirmation(""); setMessage("パスワードを変更しました"); } catch (cause) { setError(cause instanceof Error ? cause.message : "変更に失敗しました"); } } return <Shell><main className="page narrow-page"><PageHeader eyebrow="アカウント" title="アカウント設定" description="ログインIDと氏名は管理者が管理します。" /><section className="panel form-panel"><h2>パスワード変更</h2><label>現在のパスワード<input type="password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>新しいパスワード<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} /><span className={`password-strength strength-${passwordStrength(password)}`}>強度：{passwordStrength(password)}</span></label><p className="field-help">英字・数字・記号を含む8〜20文字</p><label>新しいパスワード（確認）<input type="password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label>{error && <p className="form-error">{error}</p>}{message && <p className="form-success">{message}</p>}<div className="form-actions"><button className="secondary-button" onClick={() => navigate("/dashboard")}>戻る</button><button className="primary-button" onClick={submit}>変更する</button></div></section></main></Shell>; }

function WorkspaceNewPage() { const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [sharingMode, setSharingMode] = useState("member_scoped"); const [verificationMode, setVerificationMode] = useState("none"); const [tenants, setTenants] = useState<TenantNav[]>([]); const [tenantId, setTenantId] = useState(""); const [error, setError] = useState<string | null>(null); useEffect(() => { apiJson<{ tenants: TenantNav[] }>("/api/v1/tenants").then((result) => { setTenants(result.tenants); if (result.tenants.length === 1) setTenantId(result.tenants[0].id); }).catch(() => undefined); }, []); async function submit(event: FormEvent) { event.preventDefault(); setError(null); try { await apiJson("/api/v1/workspaces", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, description, tenantId: tenantId || undefined, sharingMode, verificationMode }) }); navigate("/dashboard"); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } } return <Shell><main className="page narrow-page"><PageHeader eyebrow="新規作成" title="ワークスペースを作成" description="提出単位のフォルダです。勤務表以外の書類もまとめて管理できます。" /><form className="panel form-panel" onSubmit={submit}><label>所属テナント<select value={tenantId} onChange={(event) => setTenantId(event.target.value)} required><option value="">選択してください</option>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select></label><label>ワークスペース名<input value={name} onChange={(event) => setName(event.target.value)} placeholder="例：2026年度 年末調整" required maxLength={100} /></label><label>説明（任意）<textarea value={description} onChange={(event) => setDescription(event.target.value)} maxLength={500} rows={4} /></label><label>フォルダ方式<select value={sharingMode} onChange={(event) => setSharingMode(event.target.value)}><option value="shared_box">共有ボックス：参照権限のあるユーザーが全員分を閲覧</option><option value="member_scoped">メンバー別：自分のフォルダだけ操作、検証者は全体を閲覧</option></select></label><label>検証フラグ<select value={verificationMode} onChange={(event) => setVerificationMode(event.target.value)}><option value="none">なし：ワークスペース配下をすべてZIP化</option><option value="verified_only">あり：検証済みファイルだけZIP化</option></select></label><p className="field-help">作成すると、参加メンバーごとのフォルダが自動生成されます。</p>{error && <p className="form-error">{error}</p>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => navigate("/dashboard")}>キャンセル</button><button className="primary-button">作成する</button></div></form></main></Shell>; }

function LegacyAdminUsersPage() { const [users, setUsers] = useState<CurrentUser[]>([]); const [tenants, setTenants] = useState<TenantNav[]>([]); const [loginId, setLoginId] = useState(""); const [displayName, setDisplayName] = useState(""); const [password, setPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [role, setRole] = useState<CurrentUser["role"]>("member"); const [twoFactorRequired, setTwoFactorRequired] = useState(true); const [tenantIds, setTenantIds] = useState<string[]>([]); const [filterTenantId, setFilterTenantId] = useState(""); const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [sort, setSort] = useState("display_name"); const [order, setOrder] = useState("asc"); const [error, setError] = useState<string | null>(null); const load = () => { const params = new URLSearchParams({ q: query, status, sort, order }); if (filterTenantId) params.set("tenantId", filterTenantId); return apiJson<{ users: CurrentUser[] }>(`/api/v1/admin/users?${params}`).then((result) => setUsers(result.users)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); }; useEffect(() => { void load(); apiJson<{ tenants: TenantNav[] }>("/api/v1/tenants").then((result) => setTenants(result.tenants)).catch(() => undefined); }, [query, status, sort, order, filterTenantId]); async function create(event: FormEvent) { event.preventDefault(); setError(null); if (!passwordPolicy.test(password) || password !== confirmation) { setError("パスワードは英字・数字・記号を含む8〜20文字で、確認入力と一致させてください"); return; } try { await apiJson("/api/v1/admin/users", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ loginId, displayName, role, tenantIds, twoFactorRequired, password, passwordConfirmation: confirmation }) }); setLoginId(""); setDisplayName(""); setPassword(""); setConfirmation(""); setRole("member"); setTwoFactorRequired(true); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } } async function suspend(item: CurrentUser) { await apiJson(`/api/v1/admin/users/${item.id}/suspension`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ suspended: !item.suspendedAt }) }); load(); } async function disable(item: CurrentUser) { if (confirm(`${item.displayName}を削除（無効化）しますか？`)) { await apiJson(`/api/v1/admin/users/${item.id}`, { method: "DELETE" }); load(); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="アカウント管理" description="アカウントの追加、削除（無効化）、停止、二段階認証を管理します。" /><div className="admin-two-column"><form className="panel form-panel" onSubmit={create}><h2>アカウントを追加</h2><label>ログインID<input value={loginId} onChange={(event) => setLoginId(event.target.value)} pattern="[A-Za-z0-9_-]+" required /></label><label>氏名<input value={displayName} onChange={(event) => setDisplayName(event.target.value)} required /></label><label>権限<select value={role} onChange={(event) => setRole(event.target.value as CurrentUser["role"])}><option value="member">メンバー</option><option value="verifier">検証者</option><option value="system_operator">システム作業者</option><option value="system_admin">システム管理者</option></select></label><label className="checkbox-field"><input type="checkbox" checked={twoFactorRequired} onChange={(event) => setTwoFactorRequired(event.target.checked)} /> 二段階認証を必須にする</label><p className="field-help">システム管理者は対象外です。</p><fieldset className="tenant-assignment"><legend>所属テナント（複数選択）</legend>{tenants.map((tenant) => <label key={tenant.id}><input type="checkbox" checked={tenantIds.includes(tenant.id)} onChange={(event) => setTenantIds((current) => event.target.checked ? [...current, tenant.id] : current.filter((id) => id !== tenant.id))} /> {tenant.name}</label>)}</fieldset><label>初期パスワード<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required /><span className={`password-strength strength-${passwordStrength(password)}`}>強度：{passwordStrength(password)}</span></label><label>初期パスワード（確認）<input type="password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} required /></label>{error && <p className="form-error">{error}</p>}<button className="primary-button">追加する</button></form><section className="panel"><div className="list-heading"><div><h2>登録済みアカウント</h2><p className="field-help">検索、状態、権限、所属テナントで絞り込めます。</p></div><div className="list-tools"><input aria-label="アカウント検索" placeholder="ID・氏名を検索" value={query} onChange={(event) => setQuery(event.target.value)} /><select aria-label="状態で絞り込み" value={status} onChange={(event) => setStatus(event.target.value)}><option value="">すべての状態</option><option value="active">有効</option><option value="suspended">停止中</option><option value="disabled">削除済み</option></select><select aria-label="所属テナントで絞り込み" value={filterTenantId} onChange={(event) => setFilterTenantId(event.target.value)}><option value="">全テナント</option>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select><select aria-label="並び順" value={sort} onChange={(event) => setSort(event.target.value)}><option value="display_name">氏名順</option><option value="login_id">ログインID順</option><option value="role">権限順</option><option value="created_at">登録日順</option></select><button className="secondary-button" type="button" onClick={() => setOrder(order === "asc" ? "desc" : "asc")}>{order === "asc" ? "昇順" : "降順"}</button></div></div><div className="user-list">{users.map((item) => <div className="user-list-row" key={item.id}><div><strong>{item.displayName}</strong><small>{item.loginId} · {item.tenantNames?.join("、") || item.tenantName || "未所属"}</small></div><span className="role-badge">{roleLabels[item.role]}</span>{item.role === "system_admin" ? <span className="field-help">2FA対象外</span> : <label className="checkbox-field compact"><input type="checkbox" checked={item.twoFactorRequired ?? false} onChange={async (event) => { await apiJson(`/api/v1/admin/users/${item.id}/2fa`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ required: event.target.checked }) }); load(); }} /> 2FA必須</label>}<select className="user-tenant-select" aria-label={`${item.displayName}の所属テナント`} multiple size={Math.min(3, Math.max(1, tenants.length))} value={item.tenantIds ?? []} onChange={async (event) => { const selected = Array.from(event.target.selectedOptions, (option) => option.value); if (!selected.length) return; await apiJson(`/api/v1/admin/users/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ displayName: item.displayName, tenantIds: selected }) }); load(); }}>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select><span className={item.disabledAt ? "disabled-label" : item.suspendedAt ? "suspended-label" : "active-label"}>{item.disabledAt ? "削除済み" : item.suspendedAt ? "停止中" : "有効"}</span><div className="user-actions">{!item.disabledAt && <button className="text-button" onClick={() => suspend(item)}>{item.suspendedAt ? "停止解除" : "停止"}</button>}{!item.disabledAt && <button className="text-button danger-button" onClick={() => disable(item)}>削除</button>}{item.role !== "system_admin" && item.twoFactorEnrolled && <button className="text-button" onClick={async () => { if (confirm(`${item.displayName}の二段階認証をリセットしますか？`)) { await apiJson(`/api/v1/admin/users/${item.id}/2fa/reset`, { method: "POST" }); load(); } }}>2FAリセット</button>}</div></div>)}</div></section></div></main></Shell>; }
function AdminUsersPage() { const [users, setUsers] = useState<CurrentUser[]>([]); const [loginId, setLoginId] = useState(""); const [displayName, setDisplayName] = useState(""); const [password, setPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [role, setRole] = useState<CurrentUser["role"]>("member"); const [twoFactorRequired, setTwoFactorRequired] = useState(true); const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [sort, setSort] = useState("display_name"); const [order, setOrder] = useState("asc"); const [error, setError] = useState<string | null>(null); const load = () => { const params = new URLSearchParams({ q: query, status, sort, order }); return apiJson<{ users: CurrentUser[] }>(`/api/v1/admin/users?${params}`).then((result) => setUsers(result.users)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); }; useEffect(() => { void load(); }, [query, status, sort, order]); async function create(event: FormEvent) { event.preventDefault(); setError(null); if (!passwordPolicy.test(password) || password !== confirmation) { setError("パスワードは英字・数字・記号を含む8〜20文字で、確認入力と一致させてください"); return; } try { await apiJson("/api/v1/admin/users", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ loginId, displayName, role, twoFactorRequired, password, passwordConfirmation: confirmation }) }); setLoginId(""); setDisplayName(""); setPassword(""); setConfirmation(""); setRole("member"); setTwoFactorRequired(true); void load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } } async function suspend(item: CurrentUser) { await apiJson(`/api/v1/admin/users/${item.id}/suspension`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ suspended: !item.suspendedAt }) }); void load(); } async function disable(item: CurrentUser) { if (confirm(`${item.displayName}を削除（無効化）しますか？`)) { await apiJson(`/api/v1/admin/users/${item.id}`, { method: "DELETE" }); void load(); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="アカウント管理" description="アカウントの追加、削除（無効化）、停止、権限、二段階認証を管理します。" /><div className="admin-two-column"><form className="panel form-panel" onSubmit={create}><h2>アカウントを追加</h2><p className="field-help">勤怠データはアカウントに直接紐づきます。</p><label>ログインID<input value={loginId} onChange={(event) => setLoginId(event.target.value)} pattern="[A-Za-z0-9_-]+" required /></label><label>氏名<input value={displayName} onChange={(event) => setDisplayName(event.target.value)} required /></label><label>権限<select value={role} onChange={(event) => setRole(event.target.value as CurrentUser["role"])}><option value="member">メンバー</option><option value="verifier">検証者</option><option value="system_operator">システム作業者</option><option value="system_admin">システム管理者</option></select></label><label className="checkbox-field"><input type="checkbox" checked={twoFactorRequired} onChange={(event) => setTwoFactorRequired(event.target.checked)} /> 二段階認証を必須にする</label><p className="field-help">システム管理者は対象外です。</p><label>初期パスワード<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required /><span className={`password-strength strength-${passwordStrength(password)}`}>強度：{passwordStrength(password)}</span></label><label>初期パスワード（確認）<input type="password" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} required /></label>{error && <p className="form-error">{error}</p>}<button className="primary-button">追加する</button></form><section className="panel"><div className="list-heading"><div><h2>登録済みアカウント</h2><p className="field-help">検索、状態、権限で絞り込み、氏名・ID・権限・登録日で並び替えます。</p></div><div className="list-tools"><input aria-label="アカウント検索" placeholder="ID・氏名を検索" value={query} onChange={(event) => setQuery(event.target.value)} /><select aria-label="状態で絞り込み" value={status} onChange={(event) => setStatus(event.target.value)}><option value="">すべての状態</option><option value="active">有効</option><option value="suspended">停止中</option><option value="disabled">削除済み</option></select><select aria-label="並び順" value={sort} onChange={(event) => setSort(event.target.value)}><option value="display_name">氏名順</option><option value="login_id">ログインID順</option><option value="role">権限順</option><option value="created_at">登録日順</option></select><button className="secondary-button" type="button" onClick={() => setOrder(order === "asc" ? "desc" : "asc")}>{order === "asc" ? "昇順" : "降順"}</button></div></div><div className="user-list">{users.map((item) => <div className="user-list-row" key={item.id}><div><strong>{item.displayName}</strong><small>{item.loginId}</small></div><span className="role-badge">{roleLabels[item.role]}</span>{item.role === "system_admin" ? <span className="field-help">2FA対象外</span> : <label className="checkbox-field compact"><input type="checkbox" checked={item.twoFactorRequired ?? false} onChange={async (event) => { await apiJson(`/api/v1/admin/users/${item.id}/2fa`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ required: event.target.checked }) }); void load(); }} /> 2FA必須</label>}<span className={item.disabledAt ? "disabled-label" : item.suspendedAt ? "suspended-label" : "active-label"}>{item.disabledAt ? "削除済み" : item.suspendedAt ? "停止中" : "有効"}</span><div className="user-actions">{!item.disabledAt && <button className="text-button" onClick={() => void suspend(item)}>{item.suspendedAt ? "停止解除" : "停止"}</button>}{!item.disabledAt && <button className="text-button danger-button" onClick={() => void disable(item)}>削除</button>}{item.role !== "system_admin" && item.twoFactorEnrolled && <button className="text-button" onClick={async () => { if (confirm(`${item.displayName}の二段階認証をリセットしますか？`)) { await apiJson(`/api/v1/admin/users/${item.id}/2fa/reset`, { method: "POST" }); void load(); } }}>2FAリセット</button>}</div></div>)}</div></section></div></main></Shell>; }

function AdminWorkspacesPage() { const [workspaces, setWorkspaces] = useState<Array<{ id: string; name: string; description?: string; memberCount: number; tenantId?: string; tenantName?: string }>>([]); const [tenants, setTenants] = useState<TenantNav[]>([]); const [name, setName] = useState(""); const [tenantId, setTenantId] = useState(""); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ workspaces: typeof workspaces }>("/api/v1/admin/workspaces").then((result) => setWorkspaces(result.workspaces)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); useEffect(() => { void load(); apiJson<{ tenants: TenantNav[] }>("/api/v1/tenants").then((result) => { setTenants(result.tenants); if (!tenantId && result.tenants[0]) setTenantId(result.tenants[0].id); }).catch(() => undefined); }, []); async function create(event: FormEvent) { event.preventDefault(); setError(null); try { await apiJson("/api/v1/admin/workspaces", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, tenantId }) }); setName(""); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="ワークスペース管理" description="テナントに所属する提出単位を作成・削除します。削除は論理削除です。" /><div className="admin-two-column"><form className="panel form-panel" onSubmit={create}><h2>ワークスペースを追加</h2><label>所属テナント<select value={tenantId} onChange={(event) => setTenantId(event.target.value)} required><option value="">選択してください</option>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select></label><label>名前<input value={name} onChange={(event) => setName(event.target.value)} required maxLength={100} /></label>{error && <p className="form-error">{error}</p>}<button className="primary-button">作成する</button></form><section className="panel"><h2>ワークスペース一覧</h2>{error && <p className="form-error">{error}</p>}{workspaces.map((workspace) => <div className="workspace-row" key={workspace.id}><div><strong>{workspace.name}</strong><small>{workspace.tenantName ?? "未所属"} · {workspace.memberCount}人のメンバーフォルダ</small></div><button className="text-button" onClick={async () => { if (confirm("このワークスペースを削除しますか？")) { await apiJson(`/api/v1/admin/workspaces/${workspace.id}`, { method: "DELETE" }); load(); } }}>削除</button></div>)}</section></div></main></Shell>; }

function AdminTenantsPage() { const [tenants, setTenants] = useState<Array<{ id: string; name: string; memberCount: number; workspaceCount: number }>>([]); const [name, setName] = useState(""); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ tenants: typeof tenants }>("/api/v1/admin/tenants").then((result) => setTenants(result.tenants)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); useEffect(() => { void load(); }, []); async function create(event: FormEvent) { event.preventDefault(); try { await apiJson("/api/v1/admin/tenants", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name }) }); setName(""); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="テナント管理" description="テナントの追加・削除と、テナント単位のワークスペースを管理します。" /><div className="admin-two-column"><form className="panel form-panel" onSubmit={create}><h2>テナントを追加</h2><label>テナント名<input value={name} onChange={(event) => setName(event.target.value)} required maxLength={100} /></label><button className="primary-button">追加する</button></form><section className="panel"><h2>テナント一覧</h2>{error && <p className="form-error">{error}</p>}{tenants.map((item) => <div className="workspace-row" key={item.id}><div><strong>{item.name}</strong><small>{item.memberCount}人 / {item.workspaceCount}ワークスペース</small></div><button className="text-button" disabled={item.name === "既定テナント"} onClick={async () => { if (confirm(`${item.name}を削除しますか？`)) { await apiJson(`/api/v1/admin/tenants/${item.id}`, { method: "DELETE" }); load(); } }}>削除</button></div>)}</section></div></main></Shell>; }
function AdminExportFormatsPage() { const [users, setUsers] = useState<CurrentUser[]>([]); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ users: CurrentUser[] }>("/api/v1/admin/users?status=active&sort=display_name&order=asc").then((result) => setUsers(result.users)).catch((cause) => setError(cause instanceof Error ? cause.message : "アカウントの読み込みに失敗しました")); useEffect(() => { void load(); }, []); async function update(user: CurrentUser, exportFormat: ExportFormat) { try { await apiJson(`/api/v1/admin/users/${user.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ displayName: user.displayName, exportFormat }) }); setUsers((current) => current.map((item) => item.id === user.id ? { ...item, exportFormat } : item)); } catch (cause) { setError(cause instanceof Error ? cause.message : "出力形式の更新に失敗しました"); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="勤怠出力形式" description="アカウントごとのExcel出力形式を設定します。AAAA形式もここで割り当てます。" />{error && <p className="form-error">{error}</p>}<section className="panel"><div className="user-list">{users.map((item) => <div className="user-list-row" key={item.id}><div><strong>{item.displayName}</strong><small>{item.loginId} · {roleLabels[item.role]}</small></div><select aria-label={`${item.displayName}の出力形式`} value={item.exportFormat ?? "abcs_regular"} onChange={(event) => void update(item, event.target.value as ExportFormat)}>{Object.entries(exportFormatLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div>)}{!users.length && <p className="field-help">アカウントがありません。</p>}</div></section></main></Shell>; }
function OutputTemplatesPage() { const [templates, setTemplates] = useState<Array<{ id: string; name: string; format: ExportFormat | null; sizeBytes: number; createdAt: string }>>([]); const [file, setFile] = useState<File | null>(null); const [format, setFormat] = useState<ExportFormat>("abcs_regular"); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ templates: typeof templates }>("/api/v1/admin/templates").then((result) => setTemplates(result.templates)).catch((cause) => setError(cause instanceof Error ? cause.message : "テンプレートの読み込みに失敗しました")); useEffect(() => { void load(); }, []); async function upload(event: FormEvent) { event.preventDefault(); if (!file) { setError("ファイルを選択してください"); return; } const body = new FormData(); body.append("file", file); body.append("format", format); try { await apiJson("/api/v1/admin/templates", { method: "POST", body }); setFile(null); setError(null); void load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "テンプレートの登録に失敗しました"); } } return <Shell><main className="page"><PageHeader eyebrow="管理" title="Excelテンプレート" description="添付されたサンプルブックを出力テンプレートとして登録します。登録時に選択した形式へ紐づけます。" /><form className="panel form-panel" onSubmit={upload}><h2>テンプレートを登録</h2><label>対応形式<select value={format} onChange={(event) => setFormat(event.target.value as ExportFormat)}>{Object.entries(exportFormatLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><p className="field-help">AAAA、ABCS、休暇申請、SP報告書の元ファイルを登録してください。登録したブックを複製して値を反映し、マクロ付きブックは.xlsm、通常のブックは.xlsxで出力します。</p><label>サンプルブック<input type="file" accept=".xlsx,.xlsm" onChange={(event) => setFile(event.target.files?.[0] ?? null)} required /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-button"><Icon name="upload" />登録する</button></form><section className="panel"><div className="section-heading"><div><h2>登録済みテンプレート</h2><p className="field-help">出力時は形式ごとに最新のテンプレートを使用します。</p></div><span className="folder-badge">{templates.length} 件</span></div><div className="workspace-template-list">{templates.map((template) => <div className="workspace-template-row" key={template.id}><Icon name="file" /><strong>{template.name}</strong><small>{template.format ? exportFormatLabels[template.format] : "形式未設定"}</small><small>{Math.ceil(template.sizeBytes / 1024)} KB</small><button type="button" className="text-button danger-button" onClick={async () => { if (confirm(`${template.name}を削除しますか？`)) { await apiJson(`/api/v1/admin/templates/${template.id}`, { method: "DELETE" }); void load(); } }}>削除</button></div>)}{!templates.length && <p className="field-help">テンプレートはまだ登録されていません。</p>}</div></section></main></Shell>; }
function LegacyAdminPage() { return <Shell><main className="page"><PageHeader title="管理" description="ユーザー、ワークスペース、テンプレート、権限、月次アーカイブを管理します。" /><div className="admin-grid"><button className="admin-card" onClick={() => navigate("/admin/users")}><Icon name="folder" /><strong>アカウント管理</strong><small>追加・無効化・パスワード変更</small></button><button className="admin-card" onClick={() => navigate("/admin/export-formats")}><Icon name="file" /><strong>勤怠出力形式</strong><small>アカウントごとのExcel形式とAAAA設定</small></button><button className="admin-card" onClick={() => navigate("/admin/tenants")}><Icon name="folder" /><strong>テナント管理</strong><small>追加・削除・所属ワークスペース</small></button><button className="admin-card" onClick={() => navigate("/admin/workspaces")}><Icon name="folder" /><strong>ワークスペース管理</strong><small>提出単位を任意の名前で作成・削除</small></button><button className="admin-card" onClick={() => navigate("/admin/templates")}><Icon name="folder" /><strong>テンプレート管理</strong><small>読み取り専用フォルダへ配置</small></button><button className="admin-card" onClick={() => navigate("/admin/archive")}><Icon name="download" /><strong>月次アーカイブ</strong><small>個人フォルダを月単位でZIP化</small></button><button className="admin-card" onClick={() => navigate("/admin/audit")}><Icon name="file" /><strong>監査履歴</strong><small>操作ログを確認</small></button></div></main></Shell>; }
function AdminPage() { return <Shell><main className="page"><PageHeader title="管理" description="アカウント、勤怠出力形式、Excelテンプレート、承認・監査を管理します。" /><div className="admin-grid"><button className="admin-card" onClick={() => navigate("/admin/users")}><Icon name="folder" /><strong>アカウント管理</strong><small>追加・停止・権限・パスワード・二段階認証</small></button><button className="admin-card" onClick={() => navigate("/admin/export-formats")}><Icon name="file" /><strong>勤怠出力形式</strong><small>アカウントごとのExcel形式とAAAA設定</small></button><button className="admin-card" onClick={() => navigate("/admin/templates")}><Icon name="file" /><strong>Excelテンプレート</strong><small>添付サンプルの書式を保持して出力</small></button><button className="admin-card" onClick={() => navigate("/approvals")}><Icon name="file" /><strong>承認・提出管理</strong><small>提出された勤怠データを確認</small></button><button className="admin-card" onClick={() => navigate("/admin/audit")}><Icon name="file" /><strong>監査ログ</strong><small>操作履歴を確認</small></button></div></main></Shell>; }
function MonthlyArchivePage() { return <Shell><main className="page narrow-page"><PageHeader eyebrow="管理 / 月次アーカイブ" title="月次アーカイブ" description="個人フォルダのファイルを、月単位でZIPにまとめて保存します。" /><section className="panel archive-panel"><label>対象月<select defaultValue="2026-11"><option>2026-11</option><option>2026-10</option></select></label><div className="archive-tree"><div><Icon name="folder" /><strong>2026年11月</strong></div><div className="archive-child"><Icon name="folder" /><span>山田 太郎</span><small>勤務表ファイル 3件 / 経費・領収証 4件</small></div><div className="archive-child"><Icon name="folder" /><span>佐藤 花子</span><small>勤務表ファイル 3件 / 経費・領収証 2件</small></div></div><button className="primary-button archive-button"><Icon name="download" />ZIPでダウンロード</button><p className="field-help">ZIP内には「個人名 / 勤務表ファイル」「個人名 / 経費・領収証」のフォルダ構成を保持します。</p></section></main></Shell>; }
function TemplateAdminPage() { const [templates, setTemplates] = useState<Array<{ id: string; name: string; sizeBytes: number; workspaceId?: string | null; workspaceName?: string | null; tenantName?: string | null }>>([]); const [workspaces, setWorkspaces] = useState<WorkspaceNav[]>([]); const [workspaceId, setWorkspaceId] = useState(""); const [file, setFile] = useState<File | null>(null); const [error, setError] = useState<string | null>(null); const load = () => apiJson<{ templates: typeof templates }>("/api/v1/admin/templates").then((result) => setTemplates(result.templates)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); useEffect(() => { void load(); apiJson<{ workspaces: WorkspaceNav[] }>("/api/v1/workspaces").then((result) => setWorkspaces(result.workspaces)).catch(() => undefined); }, []); async function upload(event: FormEvent) { event.preventDefault(); if (!file) { setError("ファイルを選択してください"); return; } const body = new FormData(); body.append("file", file); if (workspaceId) body.append("workspaceId", workspaceId); try { await apiJson("/api/v1/admin/templates", { method: "POST", body }); setFile(null); setWorkspaceId(""); load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "テンプレートの追加に失敗しました"); } } async function assign(id: string, target: string) { await apiJson(`/api/v1/admin/templates/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workspaceId: target || null }) }); load(); } return <Shell><main className="page"><PageHeader eyebrow="管理 / テンプレート" title="テンプレート管理" description="テンプレートはマイドキュメントではなく、指定したテナント内ワークスペースに読み取り専用で配置します。" /><form className="panel template-upload-panel" onSubmit={upload}><div><h2>テンプレートを追加</h2><p className="field-help">ワークスペースを指定すると、そのワークスペース上部のテンプレート欄から参照できます。</p></div><label>ファイル<input type="file" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /></label><label>配置先ワークスペース<select value={workspaceId} onChange={(event) => setWorkspaceId(event.target.value)}><option value="">未紐づけ</option>{workspaces.map((workspace) => <option key={workspace.id} value={workspace.id}>{workspace.tenantName ?? "テナント"} / {workspace.name}</option>)}</select></label>{error && <p className="form-error">{error}</p>}<button className="primary-button"><Icon name="upload" />配置する</button></form><section className="panel"><h2>配置済みテンプレート</h2><div className="file-list template-list"><div className="file-list-head"><span>名前</span><span>配置先</span><span>サイズ</span><span /></div>{templates.map((template) => <div className="file-row" key={template.id}><div className="file-name"><span className="file-icon"><Icon name="file" /></span><div><strong>{template.name}</strong><small>読み取り専用</small></div></div><select aria-label={`${template.name}の配置先`} value={template.workspaceId ?? ""} onChange={(event) => assign(template.id, event.target.value)}><option value="">未紐づけ</option>{workspaces.map((workspace) => <option key={workspace.id} value={workspace.id}>{workspace.tenantName ?? "テナント"} / {workspace.name}</option>)}</select><div className="muted-cell">{Math.ceil(template.sizeBytes / 1024)} KB</div><button className="row-action danger-button" onClick={async () => { if (confirm(`${template.name}を削除しますか？`)) { await apiJson(`/api/v1/admin/templates/${template.id}`, { method: "DELETE" }); load(); } }}>削除</button></div>)}</div></section></main></Shell>; }
function AdminAuditPage() { const [events, setEvents] = useState<Array<{ id: string; action: string; entityType: string; entityId: string; details: string; createdAt: string; actorDisplayName?: string | null; actorLoginId?: string | null }>>([]); const [error, setError] = useState<string | null>(null); useEffect(() => { apiJson<{ events: typeof events }>("/api/v1/admin/audit?limit=200").then((result) => setEvents(result.events)).catch((cause) => setError(cause instanceof Error ? cause.message : "監査履歴の読み込みに失敗しました")); }, []); return <Shell><main className="page"><PageHeader eyebrow="管理 / 監査履歴" title="監査履歴" description="認証・ファイル操作・提出・承認などの操作履歴を確認できます。" />{error && <p className="form-error">{error}</p>}<section className="panel"><div className="file-list"><div className="file-list-head"><span>日時</span><span>操作者</span><span>操作</span><span>対象</span><span>詳細</span></div>{events.map((event) => <div className="file-row" key={event.id}><div className="muted-cell">{new Date(event.createdAt).toLocaleString("ja-JP")}</div><div>{event.actorDisplayName ?? event.actorLoginId ?? "システム"}</div><div><strong>{event.action}</strong></div><div className="muted-cell">{event.entityType} / {event.entityId}</div><div className="muted-cell">{event.details}</div></div>)}{!events.length && <p className="field-help">監査履歴はまだありません。</p>}</div></section></main></Shell>; }
function HomePage() { return <main className="login-page"><div className="login-brand"><span className="brand-mark">T</span><strong>Timesheet Portal</strong></div><div className="welcome-card"><p className="eyebrow">TIMESHEET PORTAL</p><h1>勤務表を、確実に提出する。</h1><p>SharePointのように、勤務表ファイルを一覧から開いて管理できます。</p><button className="primary-button" onClick={() => navigate("/login")}>ログイン画面へ</button></div></main>; }
function TwoFactorPage() { const [secret, setSecret] = useState(""); const [uri, setUri] = useState(""); const [recoveryCodes, setRecoveryCodes] = useState<string[]>([]); const [qrDataUrl, setQrDataUrl] = useState(""); const [verifyOnly, setVerifyOnly] = useState(false); const [code, setCode] = useState(""); const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false); useEffect(() => { apiJson<{ twoFactor?: { enrolled: boolean } }>("/api/v1/auth/me").then((me) => { if (me.twoFactor?.enrolled || new URLSearchParams(window.location.search).get("mode") === "verify") { setVerifyOnly(true); return; } return apiJson<{ secret: string; uri: string; recoveryCodes: string[] }>("/api/v1/auth/2fa/setup", { method: "POST" }).then(async (result) => { setSecret(result.secret); setUri(result.uri); setRecoveryCodes(result.recoveryCodes); setQrDataUrl(await QRCode.toDataURL(result.uri, { errorCorrectionLevel: "M", margin: 1, width: 240 })); }); }).catch((cause) => setError(cause instanceof Error ? cause.message : "二段階認証の準備に失敗しました")); }, []); async function verify(event: FormEvent) { event.preventDefault(); setBusy(true); setError(null); try { await apiJson("/api/v1/auth/2fa/verify", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ code }) }); navigate("/dashboard"); } catch (cause) { setError(cause instanceof Error ? cause.message : "認証コードを確認できません"); } finally { setBusy(false); } } return <main className="login-page"><div className="login-brand"><span className="brand-mark">T</span><strong>Timesheet Portal</strong></div><section className="login-card two-factor-setup"><p className="eyebrow">SECURITY SETUP</p><h1>{verifyOnly ? "二段階認証コードを入力" : "二段階認証を登録"}</h1>{verifyOnly ? <p className="two-factor-intro">登録済みの認証アプリに表示された6桁コード、または未使用のバックアップコードを入力してください。秘密鍵とQRコードは管理者がリセットするまで再表示されません。</p> : <p className="two-factor-intro">認証アプリでQRコードを読み取るか、表示された秘密鍵を登録してください。登録が完了するまでダッシュボードは利用できません。</p>}{!verifyOnly && (secret || qrDataUrl) && <div className="panel two-factor-registration"><strong>認証アプリに登録</strong>{qrDataUrl && <div className="two-factor-qr"><img src={qrDataUrl} alt="二段階認証登録用QRコード" /></div>}{secret && <div className="two-factor-secret"><span>登録用秘密鍵</span><code>{secret}</code></div>}<small>認証アプリで「TimeDock」を追加し、表示された6桁コードを入力してください。</small>{recoveryCodes.length > 0 && <div className="recovery-code-panel"><strong>バックアップコード（各1回のみ使用）</strong><p>端末を失った場合に備え、安全な場所へ保存してください。この画面を離れると再表示できません。</p><code>{recoveryCodes.join(" · ")}</code></div>}</div>}{!verifyOnly && uri && <details className="two-factor-uri"><summary>登録URIを表示</summary><code>{uri}</code></details>}<form className="login-form" onSubmit={verify}><label htmlFor="totp-code">認証コードまたはバックアップコード</label><input id="totp-code" value={code} onChange={(event) => setCode(event.target.value)} inputMode="text" pattern="[A-Za-z0-9-]{6,20}" maxLength={20} required />{error && <p className="form-error" role="alert">{error}</p>}<button type="submit" disabled={busy}>{busy ? "確認中…" : verifyOnly ? "ログインする" : "登録して続ける"}</button></form></section></main>; }
function WorkspaceDetailPage() { const workspaceId = window.location.pathname.split("/")[2] ?? ""; const [workspace, setWorkspace] = useState<WorkspaceNav & { description?: string; sharingMode?: string; verificationMode?: string } | null>(null); const [templates, setTemplates] = useState<Array<{ id: string; name: string; sizeBytes: number }>>([]); const [files, setFiles] = useState<Array<{ id: string; name: string; sizeBytes: number; category: string }>>([]); const [error, setError] = useState<string | null>(null); useEffect(() => { apiJson<{ workspaces: Array<WorkspaceNav & { description?: string; sharingMode?: string; verificationMode?: string }> }>("/api/v1/workspaces").then((result) => setWorkspace(result.workspaces.find((item) => item.id === workspaceId) ?? null)).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); apiJson<{ templates: typeof templates }>(`/api/v1/workspaces/${workspaceId}/templates`).then((result) => setTemplates(result.templates)).catch(() => undefined); apiJson<{ files: typeof files }>(`/api/v1/workspaces/${workspaceId}/files`).then((result) => setFiles(result.files)).catch(() => undefined); }, [workspaceId]); async function uploadFile(selected: File) { const body = new FormData(); body.append("file", selected); body.append("category", "other"); try { await apiJson(`/api/v1/workspaces/${workspaceId}/files`, { method: "POST", body }); const result = await apiJson<{ files: typeof files }>(`/api/v1/workspaces/${workspaceId}/files`); setFiles(result.files); } catch (cause) { setError(cause instanceof Error ? cause.message : "ファイルの追加に失敗しました"); } } async function deleteFile(file: typeof files[number]) { if (!confirm(`「${file.name}」を削除しますか？`)) return; try { await apiJson(`/api/v1/workspaces/${workspaceId}/files/${file.id}`, { method: "DELETE" }); setFiles((current) => current.filter((item) => item.id !== file.id)); } catch (cause) { setError(cause instanceof Error ? cause.message : "ファイルの削除に失敗しました"); } } return <Shell><main className="page"><PageHeader eyebrow={workspace?.tenantName ?? "テナント"} title={workspace?.name ?? "ワークスペース"} description={workspace?.description ?? "テナント内の共有ワークスペース"} /><section className="panel workspace-template-panel"><div className="section-heading"><div><h2>テンプレート</h2><p className="field-help">管理者が配置した読み取り専用ファイルです。</p></div><span className="folder-badge">{templates.length} 件</span></div>{templates.length ? <div className="workspace-template-list">{templates.map((template) => <div className="workspace-template-row" key={template.id}><Icon name="file" /><strong>{template.name}</strong><small>{Math.ceil(template.sizeBytes / 1024)} KB</small><a className="secondary-button" href={`/api/v1/workspaces/${workspaceId}/templates/${template.id}/download`}>ダウンロード</a></div>)}</div> : <p className="field-help">このワークスペースにテンプレートはありません。</p>}</section><section className="panel"><div className="section-heading"><div><h2>ワークスペースのファイル</h2><p className="field-help">勤務表、経費、領収証などをこのテナントのワークスペースに追加できます。</p></div><details className="file-action-menu"><summary aria-label="ファイル操作">⋯</summary><div className="file-action-menu-list"><label>ファイルを追加<input type="file" hidden onChange={(event) => { const selected = event.target.files?.[0]; if (selected) void uploadFile(selected); event.currentTarget.value = ""; }} /></label></div></details></div><div className="workspace-file-list">{files.map((file) => <div className="workspace-template-row" key={file.id}><Icon name="file" /><strong>{file.name}</strong><small>{Math.ceil(file.sizeBytes / 1024)} KB</small><details className="file-action-menu"><summary aria-label={`${file.name}の操作`}>⋯</summary><div className="file-action-menu-list"><a href={`/api/v1/workspaces/${workspaceId}/files/${file.id}/download`}>ダウンロード</a><button type="button" className="danger-button" onClick={() => void deleteFile(file)}>削除</button></div></details></div>)}{!files.length && <p className="field-help">ファイルはまだありません。</p>}</div></section><section className="panel"><h2>ワークスペース情報</h2>{error && <p className="form-error">{error}</p>}{workspace && <p className="field-help">方式：{workspace.sharingMode === "shared_box" ? "共有ボックス" : "メンバー別フォルダ"} / ZIP：{workspace.verificationMode === "verified_only" ? "検証済みのみ" : "全ファイル"}</p>}<p>このテナントのファイルとフォルダをここから管理します。</p></section></main></Shell>; }
function WorkspaceCreatePage() {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [sharingMode, setSharingMode] = useState("member_scoped");
  const [verificationMode, setVerificationMode] = useState("none");
  const [permissionMode, setPermissionMode] = useState("blacklist");
  const [tenantId, setTenantId] = useState("");
  const [tenants, setTenants] = useState<TenantNav[]>([]);
  const [members, setMembers] = useState<Array<{ id: string; displayName: string }>>([]);
  const [memberIds, setMemberIds] = useState<string[]>([]);
  const [permissionUserIds, setPermissionUserIds] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { apiJson<{ tenants: TenantNav[] }>("/api/v1/tenants").then((result) => { setTenants(result.tenants); if (result.tenants[0]) setTenantId(result.tenants[0].id); }).catch((cause) => setError(cause instanceof Error ? cause.message : "テナントの読み込みに失敗しました")); }, []);
  useEffect(() => { if (!tenantId) return; apiJson<{ members: typeof members }>(`/api/v1/tenants/${tenantId}/members`).then((result) => { setMembers(result.members); setMemberIds(result.members.map((member) => member.id)); }).catch((cause) => setError(cause instanceof Error ? cause.message : "テナント内ユーザーの読み込みに失敗しました")); }, [tenantId]);
  async function submit(event: FormEvent) { event.preventDefault(); setError(null); try { await apiJson("/api/v1/workspaces", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, description, tenantId, sharingMode, verificationMode, memberIds: sharingMode === "member_scoped" ? memberIds : [], permissionMode, permissionUserIds: sharingMode === "shared_box" ? permissionUserIds : [] }) }); navigate("/dashboard"); } catch (cause) { setError(cause instanceof Error ? cause.message : "作成に失敗しました"); } }
  return <Shell><main className="page narrow-page"><PageHeader eyebrow="新規作成" title="ワークスペースを作成" description="マイドキュメントと同じ形式で、テナント内のファイル置き場を作成します。" /><form className="panel form-panel" onSubmit={submit}><label>所属テナント<select value={tenantId} onChange={(event) => setTenantId(event.target.value)} required><option value="">選択してください</option>{tenants.map((tenant) => <option key={tenant.id} value={tenant.id}>{tenant.name}</option>)}</select></label><label>ワークスペース名<input value={name} onChange={(event) => setName(event.target.value)} placeholder="例：2026年度 年末調整" required maxLength={100} /></label><label>説明（任意）<textarea value={description} onChange={(event) => setDescription(event.target.value)} maxLength={500} rows={4} /></label><label>フォルダ方式<select value={sharingMode} onChange={(event) => setSharingMode(event.target.value)}><option value="shared_box">共有ボックス：参照権限のあるユーザーが全員分を閲覧</option><option value="member_scoped">メンバー別：自分のフォルダだけ操作、検証者は全体を閲覧</option></select></label>{sharingMode === "shared_box" ? <fieldset className="tenant-assignment"><legend>参照権限（テナント内ユーザー）</legend><label><input type="radio" name="permission-mode" checked={permissionMode === "blacklist"} onChange={() => setPermissionMode("blacklist")} /> ブラックリスト：選択したユーザーを除外</label><label><input type="radio" name="permission-mode" checked={permissionMode === "whitelist"} onChange={() => setPermissionMode("whitelist")} /> ホワイトリスト：選択したユーザーだけ許可</label><div className="permission-user-list">{members.map((member) => <label key={member.id}><input type="checkbox" checked={permissionUserIds.includes(member.id)} onChange={(event) => setPermissionUserIds((current) => event.target.checked ? [...current, member.id] : current.filter((id) => id !== member.id))} /> {member.displayName}</label>)}</div></fieldset> : <fieldset className="tenant-assignment"><legend>参加メンバー（テナント内ユーザー）</legend>{members.map((member) => <label key={member.id}><input type="checkbox" checked={memberIds.includes(member.id)} onChange={(event) => setMemberIds((current) => event.target.checked ? [...current, member.id] : current.filter((id) => id !== member.id))} /> {member.displayName}</label>)}</fieldset>}<label>検証フラグ<select value={verificationMode} onChange={(event) => setVerificationMode(event.target.value)}><option value="none">なし：ワークスペース配下をすべてZIP化</option><option value="verified_only">あり：検証済みファイルだけZIP化</option></select></label>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="secondary-button" onClick={() => navigate("/dashboard")}>キャンセル</button><button className="primary-button">作成する</button></div></form></main></Shell>;
}

function WorkspaceBrowserPage() {
  const workspaceId = window.location.pathname.split("/")[2] ?? "";
  const [workspace, setWorkspace] = useState<WorkspaceNav & { description?: string; sharingMode?: string; verificationMode?: string } | null>(null);
  const [templates, setTemplates] = useState<Array<{ id: string; name: string; sizeBytes: number }>>([]);
  const [files, setFiles] = useState<Array<{ id: string; name: string; sizeBytes: number; category: string }>>([]);
  const [role, setRole] = useState<CurrentUser["role"] | null>(null);
  const [permissionMode, setPermissionMode] = useState("blacklist");
  const [accessUsers, setAccessUsers] = useState<Array<{ id: string; displayName: string; selected: boolean }>>([]);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [error, setError] = useState<string | null>(null);
  async function loadFiles() { const result = await apiJson<{ files: typeof files }>(`/api/v1/workspaces/${workspaceId}/files`); setFiles(result.files); }
  useEffect(() => { apiJson<{ user: CurrentUser }>("/api/v1/auth/me").then((result) => setRole(result.user.role)).catch(() => undefined); apiJson<{ workspaces: Array<WorkspaceNav & { description?: string; sharingMode?: string; verificationMode?: string }> }>("/api/v1/workspaces").then((result) => { const found = result.workspaces.find((item) => item.id === workspaceId) ?? null; setWorkspace(found); if (found?.sharingMode === "shared_box") apiJson<{ permissionMode: string; users: typeof accessUsers }>(`/api/v1/workspaces/${workspaceId}/access`).then((access) => { setPermissionMode(access.permissionMode); setAccessUsers(access.users); }).catch(() => undefined); }).catch((cause) => setError(cause instanceof Error ? cause.message : "読み込みに失敗しました")); apiJson<{ templates: typeof templates }>(`/api/v1/workspaces/${workspaceId}/templates`).then((result) => setTemplates(result.templates)).catch(() => undefined); loadFiles().catch((cause) => setError(cause instanceof Error ? cause.message : "ファイル一覧の読み込みに失敗しました")); }, [workspaceId]);
  async function uploadFile(selected: File) { const body = new FormData(); body.append("file", selected); body.append("category", category === "all" ? "other" : category); try { await apiJson(`/api/v1/workspaces/${workspaceId}/files`, { method: "POST", body }); await loadFiles(); } catch (cause) { setError(cause instanceof Error ? cause.message : "ファイルの追加に失敗しました"); } }
  async function deleteFile(file: typeof files[number]) { if (!confirm(`「${file.name}」を削除しますか？`)) return; try { await apiJson(`/api/v1/workspaces/${workspaceId}/files/${file.id}`, { method: "DELETE" }); setFiles((current) => current.filter((item) => item.id !== file.id)); } catch (cause) { setError(cause instanceof Error ? cause.message : "ファイルの削除に失敗しました"); } }
  const visibleFiles = files.filter((file) => (!query || file.name.toLowerCase().includes(query.toLowerCase())) && (category === "all" || file.category === category));
  async function saveAccess() { const userIds = accessUsers.filter((user) => user.selected).map((user) => user.id); try { await apiJson(`/api/v1/workspaces/${workspaceId}/access`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ mode: permissionMode, userIds }) }); } catch (cause) { setError(cause instanceof Error ? cause.message : "参照権限の保存に失敗しました"); } }
  return <Shell><main className="page"><PageHeader eyebrow={workspace?.tenantName ?? "テナント"} title={workspace?.name ?? "ワークスペース"} description={workspace?.description ?? "テナント内のファイルを管理できます。"} /><div className="toolbar">{role !== "system_operator" && <label className="primary-button upload-button"><Icon name="upload" />ファイルを追加<input type="file" hidden onChange={(event) => { const selected = event.target.files?.[0]; if (selected) void uploadFile(selected); event.currentTarget.value = ""; }} /></label>}<div className="search-box"><Icon name="search" /><input aria-label="ワークスペース内を検索" placeholder="ワークスペース内を検索" value={query} onChange={(event) => setQuery(event.target.value)} /></div><select aria-label="ファイル種別" value={category} onChange={(event) => setCategory(event.target.value)}><option value="all">すべての種別</option><option value="timesheet">勤務表</option><option value="expense">経費</option><option value="receipt">領収証</option><option value="other">その他</option></select>{(role === "system_admin" || role === "verifier") && workspace?.sharingMode === "shared_box" && <details className="file-action-menu workspace-permission-menu"><summary aria-label="参照権限設定">⋯</summary><div className="file-action-menu-list permission-menu"><strong>参照権限</strong><label><input type="radio" name="workspace-permission-mode" checked={permissionMode === "blacklist"} onChange={() => setPermissionMode("blacklist")} /> ブラックリスト</label><label><input type="radio" name="workspace-permission-mode" checked={permissionMode === "whitelist"} onChange={() => setPermissionMode("whitelist")} /> ホワイトリスト</label>{accessUsers.map((user) => <label key={user.id}><input type="checkbox" checked={user.selected} onChange={(event) => setAccessUsers((current) => current.map((item) => item.id === user.id ? { ...item, selected: event.target.checked } : item))} /> {user.displayName}</label>)}<button type="button" className="primary-button" onClick={() => void saveAccess()}>保存</button></div></details>}</div><div className="folder-grid"><div className="folder-card read-only"><span className="folder-card-icon"><Icon name="folder" /></span><span><strong>テンプレート</strong><small>管理者が配置 · 読み取り専用</small></span><span className="folder-badge">{templates.length} 件</span></div><div className="folder-card"><span className="folder-card-icon personal"><Icon name="folder" /></span><span><strong>ワークスペースのファイル</strong><small>{workspace?.sharingMode === "member_scoped" ? "自分のフォルダを操作できます" : "参照権限のあるファイルを操作できます"}</small></span><span className="folder-badge">{visibleFiles.length} 件</span></div></div><div className="folder-tree"><span><Icon name="folder" />{workspace?.tenantName ?? "テナント"}</span><Icon name="chevron" /><span><Icon name="folder" />{workspace?.name ?? "ワークスペース"}</span><Icon name="chevron" /><span><Icon name="folder" />ワークスペースのファイル</span></div><div className="location-bar"><Icon name="folder" /><strong>ワークスペースのファイル</strong><span className="item-count">{visibleFiles.length} 件</span></div>{error && <p className="form-error" role="alert">{error}</p>}<section className="file-list" aria-label="ワークスペースのファイル一覧"><div className="file-list-head"><span>名前</span><span>種別</span><span>サイズ</span><span /></div>{visibleFiles.map((file) => <div className="file-row" key={file.id}><div className="file-name"><span className="file-icon"><Icon name="file" /></span><div><strong>{file.name}</strong><small>{file.category}</small></div></div><div className="muted-cell">{file.category}</div><div className="muted-cell">{Math.ceil(file.sizeBytes / 1024)} KB</div><details className="file-action-menu"><summary aria-label={`${file.name}の操作`}>⋯</summary><div className="file-action-menu-list"><a href={`/api/v1/workspaces/${workspaceId}/files/${file.id}/download`}>{"ダウンロード"}</a>{role !== "system_operator" && <button type="button" className="danger-button" onClick={() => void deleteFile(file)}>削除</button>}</div></details></div>)}{!visibleFiles.length && <p className="field-help">ファイルはまだありません。</p>}</section><section className="panel workspace-template-panel"><div className="section-heading"><div><h2>テンプレート</h2><p className="field-help">管理者が配置した読み取り専用ファイルです。</p></div><span className="folder-badge">{templates.length} 件</span></div>{templates.length ? <div className="workspace-template-list">{templates.map((template) => <div className="workspace-template-row" key={template.id}><Icon name="file" /><strong>{template.name}</strong><small>{Math.ceil(template.sizeBytes / 1024)} KB</small><a className="secondary-button" href={`/api/v1/workspaces/${workspaceId}/templates/${template.id}/download`}>ダウンロード</a></div>)}</div> : <p className="field-help">このワークスペースにテンプレートはありません。</p>}</section><section className="panel"><h2>ワークスペース情報</h2><p className="field-help">方式：{workspace?.sharingMode === "shared_box" ? "共有ボックス" : "メンバー別フォルダ"} / ZIP：{workspace?.verificationMode === "verified_only" ? "検証済みのみ" : "全ファイル"}</p></section></main></Shell>;
}

function App() { const [path, setPath] = useState(window.location.pathname); useEffect(() => { const onPopState = () => setPath(window.location.pathname); window.addEventListener("popstate", onPopState); return () => window.removeEventListener("popstate", onPopState); }, []); if (path === "/login") return <LoginPage />; if (path === "/account/2fa") return <TwoFactorPage />; if (path === "/dashboard") return <DashboardPage />; if (path === "/account") return <AccountPage />; if (path === "/attendance" || path === "/timesheets/new") return <AttendancePage />; if (path === "/workspaces/new" || path.startsWith("/workspaces/")) return <DashboardPage />; if (path.startsWith("/timesheets/")) return <TimesheetDetailPage />; if (path === "/approvals") return <ApprovalsPage />; if (path === "/admin/users") return <AdminUsersPage />; if (path === "/admin/export-formats") return <AdminExportFormatsPage />; if (path === "/admin/templates") return <OutputTemplatesPage />; if (path === "/admin/tenants" || path === "/admin/workspaces" || path === "/admin/archive") return <AdminPage />; if (path === "/admin/audit") return <AdminAuditPage />; if (path === "/admin") return <AdminPage />; return <HomePage />; }
createRoot(document.getElementById("root")!).render(<StrictMode><App /></StrictMode>);
